/**
 * The token contract the helm layer is held to (plan 030, P3.2).
 *
 * Helm components are generated by the Spartan CLI carrying the stock
 * shadcn/Spartan look, then restyled onto the lore token layer. "Restyled"
 * has to mean something a test can check, and this is it: every colour a helm
 * component paints must come from a semantic CSS variable in
 * `src/theme/tokens.css` — never a literal, never a stock Tailwind palette
 * ramp. That is what keeps the dark theme, the density tiers and the shared
 * lore-dam design language retunable from one file.
 *
 * jsdom resolves no CSS custom properties at all (it has no cascade for them),
 * so a computed-style assertion would be meaningless here. The contract is
 * therefore asserted where it actually lives — on the utility classes the
 * components emit — and the visual half belongs to the e2e layer, exactly as
 * `src/test-setup.ts` already says of colour-contrast checks.
 */

// Imported rather than taken from `vitest/globals`: this entry is compiled by
// ng-packagr under tsconfig.lib.json (`types: []`), which does not load the
// vitest globals. Only specs import it, so it never reaches an app bundle.
import { expect } from 'vitest';

/** Tailwind's stock colour ramps. None of these may appear in helm code. */
const STOCK_RAMPS = [
  'black',
  'white',
  'slate',
  'gray',
  'grey',
  'zinc',
  'neutral',
  'stone',
  'red',
  'orange',
  'amber',
  'yellow',
  'lime',
  'green',
  'emerald',
  'teal',
  'cyan',
  'sky',
  'blue',
  'indigo',
  'violet',
  'purple',
  'fuchsia',
  'pink',
  'rose',
].join('|');

/** `bg-black/10`, `dark:text-zinc-400`, `ring-blue-500/50`, … */
const STOCK_PALETTE_UTILITY = new RegExp(
  `(?:^|:)(?:bg|text|border|ring|outline|fill|stroke|divide|shadow|caret|accent|decoration|placeholder|from|via|to)-(?:${STOCK_RAMPS})(?:-\\d{1,3})?(?:\\/\\d+)?$`,
);

/** A colour written out longhand, in a class or an arbitrary value. */
const COLOUR_LITERAL = /#[0-9a-fA-F]{3,8}\b|\b(?:rgba?|hsla?|oklch|oklab|lab|lch|color-mix)\(/;

/** Every class on `root` and everything under it, de-duplicated. */
export function classesUnder(root: Element): string[] {
  const seen = new Set<string>();
  for (const el of [root, ...Array.from(root.querySelectorAll('*'))]) {
    for (const name of Array.from(el.classList)) {
      seen.add(name);
    }
  }
  return [...seen];
}

/**
 * Fails if anything under `root` paints with a stock palette class or a colour
 * literal. Mirrors P3.2's `grep` acceptance, but against the *rendered* tree —
 * so it also catches a colour smuggled in from a call site or a cva variant.
 */
export function expectOnlyTokenColours(root: Element): void {
  const offenders = classesUnder(root).filter(
    (name) => STOCK_PALETTE_UTILITY.test(name) || COLOUR_LITERAL.test(name),
  );
  expect(offenders).toEqual([]);
}

/** The same check over a raw class string (for exported class constants). */
export function expectOnlyTokenColoursIn(classString: string): void {
  const offenders = classString
    .split(/\s+/)
    .filter((name) => name && (STOCK_PALETTE_UTILITY.test(name) || COLOUR_LITERAL.test(name)));
  expect(offenders).toEqual([]);
}

/** The CDK overlay container — where every one of these primitives renders. */
export function overlayContainer(): HTMLElement {
  const container = document.querySelector<HTMLElement>('.cdk-overlay-container');
  if (!container) {
    throw new Error('No CDK overlay container: the primitive never opened.');
  }
  return container;
}
